from pathlib import Path

# Canonical marker page: map immediately after the single page H1, then details.
p = Path('public_html/index.php')
text = p.read_text()
old = """            $content .= '<h1>' . htmlspecialchars($pageTitle, ENT_QUOTES, 'UTF-8') . '</h1>';\n            $content .= MAPS_ViewMarkerInfos($mkid);\n            if (!empty($markerMapRow['mid'])) {\n                $content .= MAPS_getMarkerDetail((int) $markerMapRow['mid'], $mkid);\n            }\n"""
new = """            $content .= '<h1 class=\"maps-page-title\">' . htmlspecialchars($pageTitle, ENT_QUOTES, 'UTF-8') . '</h1>';\n            if (!empty($markerMapRow['mid'])) {\n                $content .= MAPS_getMarkerDetail((int) $markerMapRow['mid'], $mkid);\n            }\n            $content .= MAPS_ViewMarkerInfos($mkid);\n"""
if old not in text:
    raise SystemExit('marker page ordering anchor not found')
text = text.replace(old, new, 1)
p.write_text(text)

# Marker presentation card: remove duplicate H1 and use semantic, modern sections.
Path('templates/marker.thtml').write_text("""<section class=\"maps-marker-card\">\n    <div class=\"maps-marker-grid\">\n        <div class=\"maps-marker-panel maps-marker-location\">\n            <div class=\"maps-marker-address\">\n                {street}\n                {code}\n                {city}\n                {state}\n                {country}\n            </div>\n            <div class=\"maps-marker-contact\">\n                {tel}\n                {fax}\n                {web}\n            </div>\n        </div>\n        <div class=\"maps-marker-panel maps-marker-content\">\n            <div class=\"maps-marker-description\">{description}</div>\n            <div class=\"maps-marker-resources\">{ressources}</div>\n        </div>\n    </div>\n    <div class=\"maps-marker-directions-result\">{directions_table_result}</div>\n    <footer class=\"maps-marker-meta\">\n        <div class=\"maps-marker-meta-primary\">{owner} {map}</div>\n        <div class=\"maps-marker-meta-secondary\">{update}</div>\n        <div class=\"maps-marker-meta-actions\">{report} {edit}</div>\n    </footer>\n</section>\n""")

# Dedicated marker map: map first, route form and route result below it.
Path('templates/marker_map.thtml').write_text("""<style type=\"text/css\">\n.maps-page-title { margin-bottom: 1rem; }\n.maps-marker-map-shell, .maps-public-map-shell { margin: 0 0 1.25rem; }\n#map_contener_m{mid} { width: {map_width}; max-width: 100%; margin: 0; }\n#map_canvas_m{mid} { width: 100%; height: {map_height}; min-height: 320px; border-radius: 14px; overflow: hidden; background: #f2f2f2; box-shadow: 0 2px 14px rgba(0,0,0,.10); }\n.maps-route-shell { width: {map_width}; max-width: 100%; margin: .9rem 0 1.5rem; }\n.maps-directions-panel { padding: 1rem; border: 1px solid rgba(127,127,127,.25); border-radius: 12px; background: rgba(127,127,127,.06); }\n.maps-directions-panel h2 { margin: 0 0 .75rem; font-size: 1.15rem; }\n.maps-directions-panel label { display: block; margin-bottom: .4rem; font-weight: 600; }\n.maps-directions-form { display: flex; gap: .6rem; align-items: stretch; flex-wrap: wrap; }\n.maps-directions-form input[type=\"text\"] { flex: 1 1 260px; min-width: 0; box-sizing: border-box; padding: .7rem .8rem; border: 1px solid rgba(127,127,127,.4); border-radius: 8px; font: inherit; background: inherit; color: inherit; }\n.maps-directions-form input[type=\"button\"] { padding: .7rem 1rem; border: 0; border-radius: 8px; cursor: pointer; font: inherit; font-weight: 600; }\n.maps-directions-result { margin-top: 1rem; }\n.maps-marker-card { margin: 1.25rem 0; padding: 1.1rem; border: 1px solid rgba(127,127,127,.22); border-radius: 14px; background: rgba(127,127,127,.035); }\n.maps-marker-grid { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1.45fr); gap: 1rem; }\n.maps-marker-panel { min-width: 0; }\n.maps-marker-address, .maps-marker-contact, .maps-marker-description, .maps-marker-resources { line-height: 1.65; }\n.maps-marker-contact:not(:empty), .maps-marker-resources:not(:empty) { margin-top: .75rem; }\n.maps-marker-meta { display: flex; gap: .75rem 1.25rem; flex-wrap: wrap; align-items: center; margin-top: 1rem; padding-top: .8rem; border-top: 1px solid rgba(127,127,127,.2); font-size: .9em; opacity: .85; }\n.maps-marker-meta-actions { margin-left: auto; }\n.maps-marker-map-link { margin: 1rem 0 0; }\n@media (max-width: 680px) { .maps-marker-grid { grid-template-columns: 1fr; } .maps-marker-meta-actions { margin-left: 0; } #map_canvas_m{mid} { min-height: 280px; } }\n</style>\n\n{markerclusterer}\n\n<script type=\"text/javascript\">\nvar map{mid};\nvar directionsDisplay{gid};\nvar current_address{gid} = {current_address_js};\nvar alloverlays = [];\nvar map = [];\nvar zoommax = [];\nvar zoommin = [];\n\n{overlays_js}\n\nfunction initialize{mid}() {\n    var element = document.getElementById('map_canvas_m{mid}');\n    if (!element || typeof google === 'undefined' || !google.maps) { return; }\n    try {\n        map{mid} = new google.maps.Map(element, {\n            center: {lat: Number({lat_js}), lng: Number({lng_js})},\n            zoom: Number({zoom_js}),\n            mapTypeId: google.maps.MapTypeId.{map_type}\n        });\n    } catch (error) {\n        if (window.console && console.error) { console.error('Maps: initialization failed for map {mid}', error); }\n        return;\n    }\n    map[{mid}] = map{mid};\n    {overlays}\n    {markers}\n    var directionsPanel = document.getElementById('directions{gid}');\n    if (directionsPanel) {\n        directionsDisplay{gid} = new google.maps.DirectionsRenderer({ map: map{mid}, panel: directionsPanel });\n    }\n}\nif (window.addEventListener) { window.addEventListener('load', initialize{mid}, false); }\nelse { window.attachEvent('onload', initialize{mid}); }\n\nfunction get_directions{gid}() {\n    var input = document.getElementById('from_address{gid}');\n    var panel = document.getElementById('directions{gid}');\n    if (!input || !directionsDisplay{gid}) { return; }\n    if (panel) { panel.innerHTML = ''; }\n    var start = input.value;\n    if (!start) { alert({error_address_empty_js}); return; }\n    var directionsService = new google.maps.DirectionsService();\n    directionsService.route({\n        origin: start,\n        destination: current_address{gid},\n        travelMode: google.maps.TravelMode.DRIVING\n    }, function (response, status) {\n        if (status === 'OK' || status === google.maps.DirectionsStatus.OK) {\n            directionsDisplay{gid}.setDirections(response);\n            scrollToAnchor{gid}('directions_{gid}_table');\n        } else { alert({error_google_error_js} + ' (' + status + ')'); }\n    });\n}\nfunction scrollToAnchor{gid}(id) {\n    var anchor = document.getElementById(id);\n    if (anchor && anchor.scrollIntoView) { anchor.scrollIntoView({behavior: 'smooth', block: 'start'}); }\n}\n</script>\n\n<div class=\"maps-marker-map-shell\">\n    <div id=\"map_contener_m{mid}\"><div id=\"map_canvas_m{mid}\"></div></div>\n</div>\n<div class=\"maps-route-shell\">{directions_input}</div>\n{overlays_checkboxes}\n""")

# Public map page: cleaner hierarchy and map card, no 2010-style grey container.
Path('templates/map.thtml').write_text("""<style type=\"text/css\">\n.maps-public-map { margin: 0 0 1.5rem; }\n.maps-public-map-header { margin-bottom: 1rem; }\n.maps-public-map-header h1 { margin: 0 0 .55rem; line-height: 1.2; }\n.maps-public-map-description { max-width: 72ch; line-height: 1.65; }\n#map_contener_m{mid} { width: {map_width}; max-width: 100%; margin: 0; }\n#map_canvas_m{mid} { width: 100%; height: {map_height}; min-height: 320px; border-radius: 14px; overflow: hidden; background: #f2f2f2; box-shadow: 0 2px 14px rgba(0,0,0,.10); }\n.maps-map-overlays { margin-top: 1rem; }\n.maps-public-map-meta { margin-top: .8rem; font-size: .9em; opacity: .78; }\n.maps-public-map-footer { margin-top: 1.1rem; }\n.maps-public-map-actions { margin-top: .8rem; }\n@media (max-width: 680px) { #map_canvas_m{mid} { min-height: 280px; } }\n</style>\n\n{markerclusterer}\n<script type=\"text/javascript\">\nvar map{mid};\nvar directionsDisplay{gid};\nvar current_address{gid} = {current_address_js};\nvar alloverlays = [];\nvar map = [];\nvar zoommax = [];\nvar zoommin = [];\n{overlays_js}\nfunction initialize{mid}() {\n    var element = document.getElementById('map_canvas_m{mid}');\n    if (!element || typeof google === 'undefined' || !google.maps) { return; }\n    try {\n        map{mid} = new google.maps.Map(element, { center: {lat: Number({lat_js}), lng: Number({lng_js})}, zoom: Number({zoom_js}), mapTypeId: google.maps.MapTypeId.{map_type} });\n    } catch (error) {\n        if (window.console && console.error) { console.error('Maps: initialization failed for map {mid}', error); }\n        return;\n    }\n    map[{mid}] = map{mid};\n    {overlays}\n    {markers}\n}\nif (window.addEventListener) { window.addEventListener('load', initialize{mid}, false); }\nelse { window.attachEvent('onload', initialize{mid}); }\n</script>\n\n<article class=\"maps-public-map\">\n    {header}\n    <header class=\"maps-public-map-header\">\n        <h1>{name}</h1>\n        <div class=\"maps-public-map-description\">{description}</div>\n    </header>\n    <div class=\"maps-public-map-shell\">\n        <div id=\"map_contener_m{mid}\"><div id=\"map_canvas_m{mid}\"></div></div>\n    </div>\n    <div class=\"maps-map-overlays\">{overlays_checkboxes}</div>\n    <div class=\"maps-public-map-meta\">{date_and_hits}</div>\n    <div class=\"maps-public-map-footer\">{footer}</div>\n    <div class=\"maps-public-map-actions\">{edit_button}</div>\n</article>\n""")

# Modern map-list cards.
Path('templates/list_map_start.thtml').write_text("""<div id=\"maps_list\" class=\"maps-list-grid\">\n<style type=\"text/css\">\n.maps-list-grid { display: grid; gap: .85rem; margin: 1rem 0 1.5rem; }\n.maps-list-card { padding: 1rem 1.1rem; border: 1px solid rgba(127,127,127,.22); border-radius: 12px; background: rgba(127,127,127,.035); }\n.maps-list-card-title { margin: 0 0 .4rem; font-size: 1.08rem; }\n.maps-list-card-description { line-height: 1.55; }\n.maps-list-card-meta { margin-top: .6rem; font-size: .88em; opacity: .78; }\n.maps-list-card-actions { float: right; margin-left: 1rem; }\n</style>\n""")
Path('templates/list_map_item.thtml').write_text("""<article class=\"maps-list-card\">\n    <div class=\"maps-list-card-actions\">{edit_button}</div>\n    <h2 class=\"maps-list-card-title\"><a href=\"{map_detail}\">{name}</a></h2>\n    <div class=\"maps-list-card-description\">{description}</div>\n    <div class=\"maps-list-card-meta\">{update} {markers} {hits}</div>\n</article>\n""")

# Replace legacy route form markup with accessible labels and a real placeholder.
p = Path('functions.inc')
text = p.read_text()
old = """        $value = htmlentities($LANG_MAPS_1['value_directions'], ENT_QUOTES, 'UTF-8');\n        $t->set_var('current_address', htmlspecialchars($address, ENT_QUOTES, 'UTF-8'));\n        $t->set_var('current_address_js', MAPS_jsString($address));\n        $t->set_var('directions_input', '<div id=\"map_directions\"><small>' . $LANG_MAPS_1['need_directions'] . '<br><input type=\"text\" id=\"from_address' . $gid . '\" value=\"' . $value . '\" size=\"30\"><input type=\"button\" value=\"' . htmlspecialchars($LANG_MAPS_1['get_directions'], ENT_QUOTES, 'UTF-8') . '\" onclick=\"get_directions' . $gid . '();\"></small></div><a id=\"directions_' . $gid . '_table\"></a><div id=\"directions' . $gid . '\"></div>');\n"""
new = """        $value = htmlentities($LANG_MAPS_1['value_directions'], ENT_QUOTES, 'UTF-8');\n        $directionsTitle = isset($LANG_MAPS_1['directions_title']) ? $LANG_MAPS_1['directions_title'] : $LANG_MAPS_1['need_directions'];\n        $directionsStart = isset($LANG_MAPS_1['directions_start']) ? $LANG_MAPS_1['directions_start'] : $LANG_MAPS_1['from'];\n        $t->set_var('current_address', htmlspecialchars($address, ENT_QUOTES, 'UTF-8'));\n        $t->set_var('current_address_js', MAPS_jsString($address));\n        $t->set_var('directions_input', '<section id=\"map_directions\" class=\"maps-directions-panel\"><h2>'\n            . htmlspecialchars($directionsTitle, ENT_QUOTES, 'UTF-8') . '</h2><label for=\"from_address' . $gid . '\">'\n            . htmlspecialchars($directionsStart, ENT_QUOTES, 'UTF-8') . '</label><div class=\"maps-directions-form\"><input type=\"text\" id=\"from_address'\n            . $gid . '\" value=\"\" placeholder=\"' . $value . '\" autocomplete=\"street-address\"><input type=\"button\" value=\"'\n            . htmlspecialchars(trim($LANG_MAPS_1['get_directions']), ENT_QUOTES, 'UTF-8') . '\" onclick=\"get_directions' . $gid\n            . '();\"></div></section><a id=\"directions_' . $gid . '_table\"></a><div id=\"directions' . $gid . '\" class=\"maps-directions-result\"></div>');\n"""
if old not in text:
    raise SystemExit('directions markup anchor not found')
text = text.replace(old, new, 1)
p.write_text(text)

# Add concise localized labels, avoiding a raw lowercase "from" presentation.
for filename, anchor, addition in [
    ('language/english.php', "    'need_directions'       => 'Need directions? Enter your address:',\n", "    'directions_title'     => 'Plan your route',\n    'directions_start'     => 'Starting point',\n"),
    ('language/french_france_utf-8.php', "    'need_directions'       => 'Besoin de d\\'indications? Saisissez votre point de départ :',\n", "    'directions_title'     => 'Préparer votre itinéraire',\n    'directions_start'     => 'Point de départ',\n")
]:
    p = Path(filename)
    text = p.read_text()
    if 'directions_title' not in text:
        if anchor not in text:
            raise SystemExit('language anchor not found: ' + filename)
        text = text.replace(anchor, anchor + addition, 1)
        p.write_text(text)

# Release notes.
p = Path('RELEASE-NOTES-1.6.0.md')
text = p.read_text()
addition = """\n## Public layout polish\n\n- canonical marker pages now keep a single H1 and place the individual map directly below it;\n- route controls are displayed below the map in a responsive panel with explicit Starting point / Point de départ labels and placeholder text;\n- marker information uses a responsive card layout instead of the legacy 2010-era presentation;\n- public map pages use a cleaner map card, content hierarchy, metadata area and responsive spacing;\n- map listings use modern cards with separated title, description, metadata and actions.\n"""
if '## Public layout polish' not in text:
    text += addition
p.write_text(text)
